<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import AppShell from '../components/AppShell.vue'
import EvidencePlot from '../components/EvidencePlot.vue'
import StatePanel from '../components/StatePanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { consoleApi } from '../api/client'
import type { AiAttempt, Evidence, IncidentDetail, ReportView, TimelineEntry } from '../api/types'

const route=useRoute(), id=String(route.params.id);const incident=ref<IncidentDetail|null>(null),evidence=ref<Evidence[]>([]),timeline=ref<TimelineEntry[]>([]),report=ref<ReportView|null>(null),ai=ref<AiAttempt[]>([]),loading=ref(true),failed=ref(false),selected=ref(''),tab=ref<'ALL'|'METRIC'|'LOG'|'TRACE'>('ALL'),aiOpen=ref(false)
const visibleEvidence=computed(()=>tab.value==='ALL'?evidence.value:evidence.value.filter(e=>e.type===tab.value));const selectedEvidence=computed(()=>evidence.value.find(e=>e.id===selected.value)||visibleEvidence.value[0]);const evidenceTypes=computed(()=>new Set(evidence.value.map(e=>e.type)));const duration=computed(()=>{if(!incident.value)return'—';const end=incident.value.resolvedAt||incident.value.updatedAt;const seconds=Math.max(0,(new Date(end).getTime()-new Date(incident.value.startedAt).getTime())/1000);return seconds<3600?`${Math.round(seconds/60)}m`:`${(seconds/3600).toFixed(1)}h`})
const format=(v:string|null|undefined)=>v?new Intl.DateTimeFormat('zh-CN',{month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'UTC'}).format(new Date(v))+' UTC':'—'
async function load(){loading.value=true;failed.value=false;try{const [d,e,t,a]=await Promise.all([consoleApi.incident(id),consoleApi.evidence(id),consoleApi.timeline(id),consoleApi.aiAttempts(id)]);incident.value=d.data;evidence.value=e.data;timeline.value=t.data;ai.value=a.data;selected.value=e.data[0]?.id||'';try{report.value=(await consoleApi.report(id)).data}catch{report.value=null}}catch{failed.value=true}finally{loading.value=false}}
function selectTimeline(entry:TimelineEntry){if(evidence.value.some(e=>e.id===entry.evidenceId))selected.value=entry.evidenceId}
onMounted(load)
</script>
<template><AppShell section="incidents"><div class="crumb mono"><RouterLink :to="{name:'incidents'}">Incidents</RouterLink><span>/</span><span>{{id}}</span></div><h1 class="page-title">Incident Casefile</h1>
<StatePanel v-if="failed" title="无法打开 Incident 案卷" detail="API 离线、Session 过期或资源不存在。没有证据时不会生成推断。" action="重试" @action="load"/>
<div v-else-if="loading" class="skeleton" style="height:620px"/>
<template v-else-if="incident">
  <section class="case-head panel"><dl><div><dt>Incident ID</dt><dd class="mono">{{incident.id}}</dd></div><div><dt>Service</dt><dd class="mono">{{incident.primaryService}}</dd></div><div><dt>Status</dt><dd><StatusBadge :value="incident.status"/></dd></div><div><dt>First seen</dt><dd class="mono">{{format(incident.startedAt)}}</dd></div><div><dt>Duration</dt><dd class="mono">{{duration}}</dd></div><div class="finding"><dt>Deterministic finding</dt><dd>{{report?.rootCause||'证据尚不足，未形成受支持结论'}}</dd></div></dl></section>
  <div class="case-grid">
    <aside class="timeline" aria-label="Incident 叙事时间线"><button v-for="(entry,index) in timeline" :key="entry.evidenceId+entry.type" type="button" :class="{active:entry.evidenceId===selected}" @click="selectTimeline(entry)"><i>{{index+1}}</i><div><strong>{{entry.type.replaceAll('_',' ')}}</strong><time class="mono">{{format(entry.occurredAt)}}</time><p>{{entry.summary}}</p></div><b>›</b></button></aside>
    <section class="inspection panel"><header><div><p class="eyebrow">Selected evidence</p><h2>{{selectedEvidence?.type||'Evidence inspection'}}</h2></div><time class="mono">{{format(selectedEvidence?.collectedAt)}}</time></header><EvidencePlot :items="visibleEvidence" :selected="selected" @select="selected=$event"/><nav class="tabs" aria-label="证据类型"><button v-for="value in ['ALL','METRIC','LOG','TRACE'] as const" :key="value" type="button" :class="{active:tab===value}" @click="tab=value">{{value}}</button></nav><article v-if="selectedEvidence" class="evidence-detail"><div class="evidence-meta"><span class="mono">{{selectedEvidence.source}}</span><span class="mono">{{selectedEvidence.serviceName}}</span><span class="mono">importance {{selectedEvidence.importance.toFixed(1)}}</span></div><h3>受控证据摘要</h3><p>{{selectedEvidence.summary}}</p><div class="window mono">{{format(selectedEvidence.startTime)}} → {{format(selectedEvidence.endTime)}}</div></article><StatePanel v-else title="当前类型没有证据" detail="缺失证据会降低完整性，不会被模拟数据填补。"/>
      <footer class="causal"><span>⌁</span><span>Causally linked evidence</span><b v-for="(entry,index) in timeline.slice(0,8)" :key="entry.evidenceId+index" :class="{active:entry.evidenceId===selected}">{{index+1}}</b></footer>
    </section>
    <aside class="facts panel"><section><h3>Evidence completeness</h3><p v-for="type in ['METRIC','LOG','TRACE']" :key="type"><span>{{type}}</span><b :class="evidenceTypes.has(type as Evidence['type'])?'ok':'missing'">{{evidenceTypes.has(type as Evidence['type'])?'Complete':'Missing'}}</b></p><p><span>Deterministic report</span><b :class="report?'ok':'partial'">{{report?'Available':'Pending'}}</b></p></section><section><h3>Limitations</h3><ul><li v-if="!report">尚未形成受支持报告</li><li v-if="!evidenceTypes.has('TRACE')">Trace 证据缺失</li><li>仅展示脱敏摘要，不公开 raw payload</li></ul></section><section><h3>Run audit</h3><p><span>Attempt</span><b class="mono">{{incident.attempt??'—'}}</b></p><p><span>Run status</span><b>{{incident.diagnosisRunStatus??'—'}}</b></p><p><span>Support score</span><b class="mono">{{report?.supportScore?.toFixed(1)??'—'}}</b></p></section><section class="ai"><button type="button" @click="aiOpen=!aiOpen"><span>AI advisory <small>低于确定性报告</small></span><b>{{aiOpen?'−':'+'}}</b></button><div v-if="aiOpen"><p v-if="!ai.length">没有 AI 尝试记录。</p><p v-for="attempt in ai" :key="attempt.id"><StatusBadge :value="attempt.status"/><span class="mono">{{attempt.modelName||attempt.failureCode||'controlled fallback'}}</span></p></div></section></aside>
  </div>
</template></AppShell></template>
<style scoped>
