bs{display:flex;gap:25px;padding:0 20px;border-bottom:1px solid var(--line)}.tabs button{border:0;border-bottom:2px solid transparent;background:transparent;color:var(--text-muted);padding:12px 1px 10px;font:10px var(--font-mono);cursor:pointer}.tabs button.active{color:oklch(.82 .11 288);border-color:var(--accent)}.evidence-detail{padding:20px;min-height:230px}.evidence-meta{display:flex;gap:18px;color:var(--text-muted);font-size:9px}.evidence-detail h3{font-size:12px;margin:24px 0 8px}.evidence-detail p{color:var(--text-soft);line-height:1.75;white-space:pre-wrap}.window{margin-top:25px;color:var(--text-muted);font-size:9px}.causal{display:flex;align-items:center;gap:10px;border-top:1px solid var(--line);padding:12px 20px;color:var(--text-muted);font-size:10px}.causal b{width:19px;height:19px;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;font:9px var(--font-mono)}.causal b.active{border-color:var(--accent);color:var(--accent)}.facts{padding:18px}.facts section{padding:0 0 17px;margin:0 0 17px;border-bottom:1px solid var(--line)}.facts section:last-child{border:0;margin:0;padding:0}.facts h3{font-size:12px;margin:0 0 12px}.facts p{display:flex;justify-content:space-between;gap:12px;color:var(--text-soft);font-size:10px}.facts p b{font-weight:500}.facts .ok{color:var(--success)}.facts .missing{color:var(--critical)}.facts .partial{color:var(--warning)}.facts ul{padding-left:16px;color:var(--text-muted);font-size:10px;line-height:1.65}.ai>button{width:100%;border:0;background:transparent;color:var(--text);display:flex;justify-content:space-between;padding:0;cursor:pointer;text-align:left}.ai small{display:block;color:var(--text-muted);font-weight:400;margin-top:4px}.ai>div{margin-top:12px}.ai>div p{display:grid;gap:5px}.ai>div span{font-size:9px;color:var(--text-muted)}
@media(max-width:1250px){.case-grid{grid-template-columns:245px minmax(460px,1fr)}.facts{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.facts section{border-bottom:0;border-right:1px solid var(--line);padding-right:16px}.facts section:last-child{border:0}.case-head dl{grid-template-columns:repeat(3,1fr)}.case-head .finding{grid-column:1/-1;border-top:1px solid var(--line)}}@media(max-width:900px){.case-grid{grid-template-columns:1fr}.timeline{display:flex;overflow-x:auto;padding-bottom:6px}.timeline::before{display:none}.timeline button{min-width:230px}.facts{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.case-head dl{grid-template-columns:repeat(2,1fr)}.case-head dl>div{border-bottom:1px solid var(--line)}.case-head .finding{grid-column:1/-1}.facts{grid-template-columns:1fr}.facts section{border-right:0;border-bottom:1px solid var(--line)}.evidence-meta{flex-wrap:wrap}.causal b{display:none}}
</style>
